1	import React, { useEffect, useState } from 'react';
2	import type { Feature } from '../../router/routes';
3	
4	// Projects feature: add a project and pick which client it is for, then list every project showing
5	// the client's NAME. Opening a project (project-open-<id>) reveals its detail: the invoices raised
6	// against it, their running total, and a form to add another. Owns its own state; talks to its own
7	// /api/projects and /api/invoices endpoints and reads /api/clients to populate the client picker.
8	// data-testid anchors follow the spec's conventions.
9	type Client = { id: number; name: string; email: string };
10	type Project = {
11	  id: number;
12	  name: string;
13	  clientId: number;
14	  clientName: string;
15	  archived: boolean;
16	};
17	type Invoice = {
18	  id: number;
19	  projectId: number;
20	  amount: number;
21	  amountDue: number;
22	  status: string;
23	  issuedDate: string;
24	  dueDate: string;
25	};
26	type Task = { id: number; projectId: number; title: string; done: boolean };
27	type Tag = { id: number; name: string };
28	type Note = { id: number; targetType: string; targetId: number; text: string; at: string };
29	
30	type LineItem = {
31	  id: number;
32	  invoiceId: number;
33	  description: string;
34	  qty: number;
35	  unitPrice: number;
36	};
37	
38	type Payment = { id: number; invoiceId: number; amount: number; date: string };
39	
40	function money(amount: number): string {
41	  return `$${Number(amount).toFixed(2)}`;
42	}
43	
44	// One charge line while it is being edited on screen: the fields are held as raw strings so the
45	// inputs stay controlled and the total can recompute live as they change.
46	type EditItem = { id: number; description: string; qty: string; unitPrice: string };
47	
48	// An opened invoice's detail: the things it is charging for, listed as line items (description, how
49	// many, price each), the total worked out for you, and a form to add another line. Each line can be
50	// changed in place (save) or removed, and the total re-derives from whatever lines remain. Owns its
51	// own line-item state, scoped to the one invoice it is showing.
52	function InvoiceDetail({
53	  invoiceId,
54	  onChange,
55	  onClose,
56	}: {
57	  invoiceId: number;
58	  onChange: () => void;
59	  onClose: () => void;
60	}) {
61	  const [items, setItems] = useState<EditItem[]>([]);
62	  const [description, setDescription] = useState('');
63	  const [qty, setQty] = useState('');
64	  const [unitPrice, setUnitPrice] = useState('');
65	  const [payments, setPayments] = useState<Payment[]>([]);
66	  const [paymentAmount, setPaymentAmount] = useState('');
67	  const [paymentDate, setPaymentDate] = useState('');
68	
69	  async function load() {
70	    const res = await fetch(`/api/invoices/${invoiceId}/line-items`);
71	    const rows: LineItem[] = await res.json();
72	    setItems(
73	      rows.map((li) => ({
74	        id: li.id,
75	        description: li.description,
76	        qty: String(li.qty),
77	        unitPrice: String(li.unitPrice),
78	      })),
79	    );
80	  }
81	
82	  async function loadPayments() {
83	    const res = await fetch(`/api/invoices/${invoiceId}/payments`);
84	    setPayments(await res.json());
85	  }
86	
87	  async function submitPayment(e: React.FormEvent) {
88	    e.preventDefault();
89	    const value = Number(paymentAmount);
90	    if (paymentAmount.trim() === '' || !Number.isFinite(value) || value <= 0) {
91	      return;
92	    }
93	    if (paymentDate.trim() === '') {
94	      return;
95	    }
96	    await fetch(`/api/invoices/${invoiceId}/payments`, {
97	      method: 'POST',
98	      headers: { 'Content-Type': 'application/json' },
99	      body: JSON.stringify({ amount: value, date: paymentDate }),
100	    });
101	    setPaymentAmount('');
102	    setPaymentDate('');
103	    await loadPayments();
104	  }
105	
106	  useEffect(() => {
107	    void load();
108	    void loadPayments();
109	  }, [invoiceId]);
110	
111	  function editField(id: number, field: 'description' | 'qty' | 'unitPrice', value: string) {
112	    setItems((prev) => prev.map((li) => (li.id === id ? { ...li, [field]: value } : li)));
113	  }
114	
115	  function amountOf(li: EditItem): number {
116	    const line = Number(li.qty) * Number(li.unitPrice);
117	    return Number.isFinite(line) ? line : 0;
118	  }
119	
120	  async function save(li: EditItem) {
121	    if (!li.description.trim() || li.qty.trim() === '' || li.unitPrice.trim() === '') {
122	      return;
123	    }
124	    await fetch(`/api/invoices/${invoiceId}/line-items/${li.id}/update`, {
125	      method: 'POST',
126	      headers: { 'Content-Type': 'application/json' },
127	      body: JSON.stringify({
128	        description: li.description,
129	        qty: Number(li.qty),
130	        unitPrice: Number(li.unitPrice),
131	      }),
132	    });
133	    await load();
134	    onChange();
135	  }
136	
137	  async function remove(id: number) {
138	    await fetch(`/api/invoices/${invoiceId}/line-items/${id}/remove`, { method: 'POST' });
139	    await load();
140	    onChange();
141	  }
142	
143	  async function submit(e: React.FormEvent) {
144	    e.preventDefault();
145	    if (!description.trim() || qty.trim() === '' || unitPrice.trim() === '') {
146	      return;
147	    }
148	    await fetch(`/api/invoices/${invoiceId}/line-items`, {
149	      method: 'POST',
150	      headers: { 'Content-Type': 'application/json' },
151	      body: JSON.stringify({
152	        description,
153	        qty: Number(qty),
154	        unitPrice: Number(unitPrice),
155	      }),
156	    });
157	    setDescription('');
158	    setQty('');
159	    setUnitPrice('');
160	    await load();
161	    onChange();
162	  }
163	
164	  const total = items.reduce((sum, li) => sum + amountOf(li), 0);
165	
166	  return (
167	    <section data-testid="invoice-detail">
168	      <button data-testid="invoice-detail-close" type="button" onClick={onClose}>
169	        Back to invoices
170	      </button>
171	
172	      <table data-testid="invoice-lineitems-table">
173	        <tbody>
174	          {items.map((li) => (
175	            <tr key={li.id} data-testid={`lineitem-row-${li.id}`}>
176	              <td>
177	                <input
178	                  data-testid="lineitem-description"
179	                  value={li.description}
180	                  onChange={(e) => editField(li.id, 'description', e.target.value)}
181	                />
182	              </td>
183	              <td>
184	                <input
185	                  data-testid="lineitem-qty"
186	                  value={li.qty}
187	                  onChange={(e) => editField(li.id, 'qty', e.target.value)}
188	                />
189	              </td>
190	              <td>
191	                <input
192	                  data-testid="lineitem-unitprice"
193	                  value={li.unitPrice}
194	                  onChange={(e) => editField(li.id, 'unitPrice', e.target.value)}
195	                />
196	              </td>
197	              <td data-testid="lineitem-amount">{money(amountOf(li))}</td>
198	              <td>
199	                <button
200	                  data-testid={`lineitem-save-${li.id}`}
201	                  type="button"
202	                  onClick={() => save(li)}
203	                >
204	                  Save
205	                </button>
206	                <button
207	                  data-testid={`lineitem-remove-${li.id}`}
208	                  type="button"
209	                  onClick={() => remove(li.id)}
210	                >
211	                  Remove
212	                </button>
213	              </td>
214	            </tr>
215	          ))}
216	        </tbody>
217	      </table>
218	
219	      <p data-testid="invoice-amount">{money(total)}</p>
220	
221	      <form data-testid="lineitem-form" onSubmit={submit}>
222	        <input
223	          data-testid="lineitem-form-description"
224	          placeholder="Description"
225	          value={description}
226	          onChange={(e) => setDescription(e.target.value)}
227	        />
228	        <input
229	          data-testid="lineitem-form-qty"
230	          placeholder="How many"
231	          value={qty}
232	          onChange={(e) => setQty(e.target.value)}
233	        />
234	        <input
235	          data-testid="lineitem-form-unitprice"
236	          placeholder="Price each"
237	          value={unitPrice}
238	          onChange={(e) => setUnitPrice(e.target.value)}
239	        />
240	        <button data-testid="lineitem-form-submit" type="submit">
241	          Add line item
242	        </button>
243	      </form>
244	
245	      <table data-testid="invoice-payments-table">
246	        <tbody>
247	          {payments.map((p) => (
248	            <tr key={p.id} data-testid={`payment-row-${p.id}`}>
249	              <td data-testid="payment-amount">{money(p.amount)}</td>
250	              <td data-testid="payment-date">{p.date}</td>
251	            </tr>
252	          ))}
253	        </tbody>
254	      </table>
255	
256	      <form data-testid="payment-form" onSubmit={submitPayment}>
257	        <input
258	          data-testid="payment-form-amount"
259	          placeholder="Amount paid"
260	          value={paymentAmount}
261	          onChange={(e) => setPaymentAmount(e.target.value)}
262	        />
263	        <input
264	          data-testid="payment-form-date"
265	          type="date"
266	          value={paymentDate}
267	          onChange={(e) => setPaymentDate(e.target.value)}
268	        />
269	        <button data-testid="payment-form-submit" type="submit">
270	          Record payment
271	        </button>
272	      </form>
273	    </section>
