1	package net.officefloor.hq.app;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.Map;
6	import org.springframework.context.annotation.Profile;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.web.bind.annotation.PostMapping;
9	import org.springframework.web.bind.annotation.RequestBody;
10	import org.springframework.web.bind.annotation.RequestMapping;
11	import org.springframework.web.bind.annotation.RestController;
12	
13	/**
14	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
15	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
16	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
17	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
18	 *
19	 * <p>{@link #seed} is a plain sequence of one {@code seed*} method per entity. Teaching a new entity
20	 * to the harness is therefore additive: add its {@code seed*} method, call it from {@link #seed},
21	 * and add its {@code TRUNCATE} to {@link #reset} — no existing entity's code is touched.
22	 */
23	@Profile("harness")
24	@RestController
25	@RequestMapping("/__test__")
26	public class TestSupportController {
27	
28	    private final Audit audit;
29	    private final JdbcTemplate jdbc;
30	
31	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
32	        this.audit = audit;
33	        this.jdbc = jdbc;
34	    }
35	
36	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
37	    @PostMapping("/reset")
38	    public void reset() {
39	        audit.clear();
40	        // Referential integrity is dropped for the duration so the tables can be truncated (and
41	        // their identity counters restarted) regardless of FK order (e.g. projects -> clients).
42	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
43	        for (String table : List.of("notes", "project_tags", "tags", "tasks", "payments",
44	                "line_items", "invoices", "contacts", "projects", "clients")) {
45	            jdbc.execute("TRUNCATE TABLE " + table + " RESTART IDENTITY");
46	        }
47	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
48	    }
49	
50	    /** Insert the fixture a spec needs; each entity is seeded by its own {@code seed*} method. */
51	    @PostMapping("/seed")
52	    public void seed(@RequestBody Map<String, Object> fixture) {
53	        seedClients(fixture);
54	        seedProjects(fixture);
55	        seedContacts(fixture);
56	        seedInvoices(fixture);
57	        seedPayments(fixture);
58	        seedTasks(fixture);
59	        seedTags(fixture);
60	        seedNotes(fixture);
61	        seedProjectTags(fixture);
62	    }
63	
64	    private void seedClients(Map<String, Object> fixture) {
65	        for (Map<String, Object> c : rows(fixture, "clients")) {
66	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
67	                    id(c, "id"), c.get("name"), c.get("email"));
68	        }
69	    }
70	
71	    private void seedProjects(Map<String, Object> fixture) {
72	        for (Map<String, Object> p : rows(fixture, "projects")) {
73	            jdbc.update("INSERT INTO projects (id, name, client_id) VALUES (?, ?, ?)",
74	                    id(p, "id"), p.get("name"), id(p, "clientId"));
75	        }
76	    }
77	
78	    private void seedContacts(Map<String, Object> fixture) {
79	        for (Map<String, Object> ct : rows(fixture, "contacts")) {
80	            jdbc.update(
81	                    "INSERT INTO contacts (id, client_id, name, email, role) VALUES (?, ?, ?, ?, ?)",
82	                    id(ct, "id"), id(ct, "clientId"), ct.get("name"), ct.get("email"),
83	                    ct.get("role"));
84	        }
85	    }
86	
87	    private void seedInvoices(Map<String, Object> fixture) {
88	        for (Map<String, Object> in : rows(fixture, "invoices")) {
89	            // Insert only the columns the fixture supplies, so the table's own defaults apply when a
90	            // fixture omits them (a plain null would trip the NOT NULL columns). status defaults to
91	            // DRAFT and amount defaults to 0 — an invoice's amount is derived from its line items,
92	            // so fixtures list lineItems rather than a single typed amount.
93	            new Insert("invoices")
94	                    .set("id", id(in, "id"))
95	                    .set("project_id", id(in, "projectId"))
96	                    .set("status", in.get("status") == null ? "DRAFT" : in.get("status").toString())
97	                    .setIfPresent("amount", asDouble(in.get("amount")))
98	                    .setIfPresent("issued_date", asText(in.get("issuedDate")))
99	                    .setIfPresent("due_date", asText(in.get("dueDate")))
100	                    .run();
101	            seedLineItems(in);
102	        }
103	    }
104	
105	    private void seedLineItems(Map<String, Object> invoice) {
106	        long invoiceId = id(invoice, "id");
107	        for (Map<String, Object> li : rows(invoice, "lineItems")) {
108	            jdbc.update(
109	                    "INSERT INTO line_items (id, invoice_id, description, qty, unit_price)"
110	                            + " VALUES (?, ?, ?, ?, ?)",
111	                    id(li, "id"), invoiceId, li.get("description"),
112	                    ((Number) li.get("qty")).intValue(),
113	                    ((Number) li.get("unitPrice")).doubleValue());
114	        }
115	    }
116	
117	    private void seedPayments(Map<String, Object> fixture) {
118	        List<Map<String, Object>> payments = rows(fixture, "payments");
119	        for (Map<String, Object> p : payments) {
120	            jdbc.update(
121	                    "INSERT INTO payments (id, invoice_id, amount, paid_date) VALUES (?, ?, ?, ?)",
122	                    id(p, "id"), id(p, "invoiceId"), asDouble(p.get("amount")),
123	                    asText(p.get("date")));
124	        }
125	        if (!payments.isEmpty()) {
126	            // Seeding explicit ids does not advance H2's identity counter, so bump it past the
127	            // seeded rows or the app's next generated payment id would collide with a fixture id.
128	            Long next = jdbc.queryForObject("SELECT MAX(id) + 1 FROM payments", Long.class);
129	            jdbc.execute("ALTER TABLE payments ALTER COLUMN id RESTART WITH " + next);
130	        }
131	    }
132	
133	    private void seedTasks(Map<String, Object> fixture) {
134	        for (Map<String, Object> t : rows(fixture, "tasks")) {
135	            jdbc.update("INSERT INTO tasks (id, project_id, title, done) VALUES (?, ?, ?, ?)",
136	                    id(t, "id"), id(t, "projectId"), t.get("title"),
137	                    Boolean.TRUE.equals(t.get("done")));
138	        }
139	    }
140	
141	    private void seedTags(Map<String, Object> fixture) {
142	        for (Map<String, Object> tg : rows(fixture, "tags")) {
143	            jdbc.update("INSERT INTO tags (id, name) VALUES (?, ?)", id(tg, "id"), tg.get("name"));
144	        }
145	    }
146	
147	    private void seedNotes(Map<String, Object> fixture) {
148	        List<Map<String, Object>> notes = rows(fixture, "notes");
149	        for (Map<String, Object> n : notes) {
150	            jdbc.update(
151	                    "INSERT INTO notes (id, target_type, target_id, text, created_at)"
152	                            + " VALUES (?, ?, ?, ?, ?)",
153	                    id(n, "id"), n.get("targetType"), id(n, "targetId"), n.get("text"),
154	                    n.get("at").toString());
155	        }
156	        if (!notes.isEmpty()) {
157	            // Seeding explicit ids does not advance H2's identity counter, so bump it past the
158	            // seeded rows or the app's next generated note id would collide with a fixture id.
159	            Long next = jdbc.queryForObject("SELECT MAX(id) + 1 FROM notes", Long.class);
160	            jdbc.execute("ALTER TABLE notes ALTER COLUMN id RESTART WITH " + next);
161	        }
162	    }
163	
164	    private void seedProjectTags(Map<String, Object> fixture) {
165	        for (Map<String, Object> pt : rows(fixture, "projectTags")) {
166	            jdbc.update("INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
167	                    id(pt, "projectId"), id(pt, "tagId"));
168	        }
169	    }
170	
171	    /** The list of fixture rows under {@code key}, or an empty list when the fixture omits it. */
172	    @SuppressWarnings("unchecked")
173	    private static List<Map<String, Object>> rows(Map<String, Object> fixture, String key) {
174	        return (List<Map<String, Object>>) fixture.getOrDefault(key, List.of());
175	    }
176	
177	    /** A fixture id column: JSON numbers arrive as {@link Number}, the tables use {@code BIGINT}. */
178	    private static long id(Map<String, Object> row, String key) {
179	        return ((Number) row.get(key)).longValue();
180	    }
181	
182	    private static Double asDouble(Object value) {
183	        return value == null ? null : ((Number) value).doubleValue();
184	    }
185	
186	    private static String asText(Object value) {
187	        return value == null ? null : value.toString();
188	    }
189	
190	    /**
191	     * Builds an {@code INSERT} whose column set is decided per row, so a fixture can omit a column
192	     * and let the table's own default apply (a bare null would trip a NOT NULL column). Required
193	     * columns are added with {@link #set}; optional ones with {@link #setIfPresent}.
194	     */
195	    private final class Insert {
196	        private final String table;
197	        private final StringBuilder cols = new StringBuilder();
198	        private final StringBuilder marks = new StringBuilder();
199	        private final List<Object> args = new ArrayList<>();
200	
201	        Insert(String table) {
202	            this.table = table;
203	        }
204	
205	        Insert set(String column, Object value) {
206	            if (cols.length() > 0) {
207	                cols.append(", ");
208	                marks.append(", ");
209	            }
210	            cols.append(column);
211	            marks.append("?");
212	            args.add(value);
213	            return this;
214	        }
215	
216	        Insert setIfPresent(String column, Object value) {
217	            return value == null ? this : set(column, value);
218	        }
219	
220	        void run() {
221	            jdbc.update("INSERT INTO " + table + " (" + cols + ") VALUES (" + marks + ")",
222	                    args.toArray());
223	        }
224	    }
225	}
